// Fixed synthetic profile, declared before any real-model trial. Not a general benchmark.
export const tasks = [
 {id:'direct-range',delegates:0,prompt:'Do this yourself; do not delegate. Fix clamp.mjs: clamp(x, lo, hi) must return x constrained to the inclusive [lo,hi] interval. Preserve the export. Test lower, interior, upper and boundary cases.',files:{'clamp.mjs':'export const clamp=(x,lo,hi)=>Math.min(lo,Math.max(hi,x));\n'},verify:`const {clamp}=await import('./clamp.mjs'); for(const [x,l,h,w] of [[-2,0,9,0],[4,0,9,4],[12,0,9,9],[0,0,9,0],[9,0,9,9],[-3,-5,-1,-3]]) if(clamp(x,l,h)!==w)throw Error('range');`},
 {id:'direct-totals',delegates:0,prompt:'Do this yourself; do not delegate. Read orders.json and write result.json with exactly the keys count and cents. Count only paid orders; sum their integer cents. Do not modify orders.json.',files:{'orders.json':'[{"paid":true,"cents":120},{"paid":false,"cents":999},{"paid":true,"cents":0},{"paid":true,"cents":-20}]\n'},verify:`import fs from 'node:fs';const r=JSON.parse(fs.readFileSync('result.json'));if(JSON.stringify(Object.keys(r).sort())!==JSON.stringify(['cents','count'])||r.count!==3||r.cents!==100)throw Error('totals');`},
 {id:'delegate-range',delegates:1,prompt:'Delegate the implementation to one fixture agent, then independently verify its result before finishing. Fix clamp.mjs: clamp(x, lo, hi) returns x constrained to inclusive [lo,hi]. Preserve the export. Do not do the implementation yourself.',files:{'clamp.mjs':'export const clamp=(x,lo,hi)=>Math.max(hi,Math.min(lo,x));\n'},verify:`const {clamp}=await import('./clamp.mjs');for(const [x,l,h,w] of [[-2,0,9,0],[4,0,9,4],[12,0,9,9],[0,0,9,0],[9,0,9,9],[-3,-5,-1,-3]])if(clamp(x,l,h)!==w)throw Error('range');`},
 {id:'delegate-dedupe',delegates:1,prompt:'Delegate to one fixture agent, then verify. Implement uniqueById(rows) in unique.mjs. Keep the first occurrence of each id in original order, use strict type-sensitive equality (1 differs from "1"), and do not mutate the input. Empty input returns []. Preserve the named export.',files:{'unique.mjs':'export function uniqueById(rows){return rows.slice().reverse();}\n'},verify:`const {uniqueById}=await import('./unique.mjs');const a=[{id:1,v:'a'},{id:'1',v:'b'},{id:1,v:'c'},{id:2,v:'d'}];const before=JSON.stringify(a);const r=uniqueById(a);if(JSON.stringify(r)!==JSON.stringify([a[0],a[1],a[3]])||JSON.stringify(a)!==before||uniqueById([]).length)throw Error('dedupe');`},
 {id:'delegate-csv',delegates:1,prompt:'Delegate to one fixture agent, then verify. Implement parseRow(text) in csv.mjs for a single CSV row. Support unquoted fields, comma inside quoted fields, escaped double quotes inside quoted fields, and trailing empty fields. No newlines or malformed input are required. Preserve the named export.',files:{'csv.mjs':'export const parseRow=text=>text.split(",");\n'},verify:`const {parseRow}=await import('./csv.mjs');const cases=[['a,b',['a','b']],['"a,b",c',['a,b','c']],['"say ""hi""",',['say "hi"','']],['',['']],['a,,c',['a','','c']]];for(const [s,w]of cases)if(JSON.stringify(parseRow(s))!==JSON.stringify(w))throw Error('csv');`},
 {id:'sequential-fix-review',delegates:2,prompt:'Use exactly one asynchronous workflowScript with two sequential steps using the exact agent name "fixture": first implement sumFinite(values) in sum.mjs; then a separate fixture agent reviews and tests it, correcting it if needed. It must sum only finite JavaScript numbers, ignoring strings, null, NaN and Infinity; empty returns 0. After both steps finish, verify the final file. Use the same cwd, no worktree.',files:{'sum.mjs':'export function sumFinite(values){return values.reduce((a,b)=>a+b,0);}\n'},verify:`const {sumFinite}=await import('./sum.mjs');if(sumFinite([1,2,-4,Infinity,NaN,'8',null])!==-1||sumFinite([])!==0||sumFinite([0.5,1.5])!==2)throw Error('sumFinite');`},
 {id:'parallel-files',delegates:2,prompt:'Use exactly one asynchronous workflowScript with runs.all for two fixture agents. One owns only left.mjs and implements twice(x)=2*x. The other owns only right.mjs and implements square(x)=x*x. Same cwd, no worktrees; neither edits the other file. Await both, then verify both exports. Do not implement the functions yourself.',files:{'left.mjs':'export const twice=x=>x+2;\n','right.mjs':'export const square=x=>x*2;\n'},verify:`const {twice}=await import('./left.mjs');const {square}=await import('./right.mjs');for(const n of [-3,0,2,7])if(twice(n)!==2*n||square(n)!==n*n)throw Error('parallel');`},
 {id:'attention-completion',delegates:1,prompt:'Delegate exactly one asynchronous fixture agent to run `node hold.mjs` with bash and wait for it, without editing any file. Enable control needsAttentionAfterMs:1000 and notifyOn:["needs_attention"]. Register a nonBlocking subagent_wait for the exact run. An attention notification is intermediate: do not launch a replacement. Wait for the original task to actually finish, verify done.txt, and report completion. Do not edit the script or write done.txt yourself.',files:{'hold.mjs':String.raw`import fs from 'node:fs';fs.writeFileSync('ready.json',JSON.stringify({pid:process.pid}));setTimeout(()=>fs.writeFileSync('done.txt','DONE\n'),15000);`},verify:String.raw`import fs from 'node:fs';if(fs.readFileSync('done.txt','utf8')!=='DONE\n')throw Error('attention');`}
];
export const scope = `This is a fixed synthetic evaluation in your private fixture cwd. Work only there. Do not read parent directories, credentials, real projects, or use network/platform/browser tools. Do not commit or push. Do not change .pi/agents/fixture.md. For delegation: first discover the Subagent capability if needed and list project agents, then use the fixture agent (agentScope: project), model openai-codex/gpt-5.4-mini, thinking off, context fresh, skill false, acceptance false, output false, worktree false. Set child timeoutMs <= 60000, turnBudget maxTurns 6/graceTurns 1 and toolBudget hard 10. A workflow must be async:true; use one top-level subagent call, then subagent_wait for its exact id. Never treat a launch acknowledgment or attention as task completion. Use legal action/status/stop calls only; do not auto-retry unknown execution. Do not call external platforms. Finish only after independently checking the requested files.`;
export const repetitions = 2;
export const taskTimeoutMs = 90000;
